```js
export function compareRows(a, b) {
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1
  if (a.id === b.id) return 0
  return a.id < b.id ? -1 : 1
}

export function encodeCursor(row) {
  return Buffer.from(JSON.stringify({ createdAt: row.createdAt, id: row.id }), 'utf8').toString('base64url')
}

export function decodeCursor(cursor) {
  if (!cursor) return null
  try {
    const value = JSON.parse(Buffer.from(String(cursor), 'base64url').toString('utf8'))
    if (typeof value?.createdAt === 'string' && typeof value?.id === 'string') {
      return { createdAt: value.createdAt, id: value.id }
    }
    return null
  } catch { return null }
}

export function isAfter(row, position) {
  if (!position) return true
  return compareRows(row, position) > 0
}
```

